/* Atlético Madrid DNA — rojiblanco fine stripes on warm plaster, colchonero navy */
.theme-atletico-madrid {
  --bg: oklch(0.977 0.003 67.8);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.938 0.008 56.3);
  --fg: oklch(0.328 0.117 276.6);
  --fg-muted: oklch(0.626 0.008 67.7);
  --accent: oklch(0.591 0.234 27.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.328 0.117 276.6);
  --line: oklch(0.889 0.011 63.3);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.591 0.234 27.3);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Barlow Condensed", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-atletico-madrid h1,
.theme-atletico-madrid h2,
.theme-atletico-madrid h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-atletico-madrid { --font-ui: var(--font-display); }
.theme-atletico-madrid h1, .theme-atletico-madrid h2 { text-transform: uppercase; }
.theme-atletico-madrid button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-atletico-madrid { background-image: repeating-linear-gradient(90deg, oklch(0.55 0.19 25 / 7%) 0 22px, transparent 22px 44px); background-size: 100% 300px; background-repeat: no-repeat; }
.theme-atletico-madrid h1 { color: var(--accent-2); font-weight: 700; }
.theme-atletico-madrid h1 em, .theme-atletico-madrid h2 { color: var(--accent); }

/* depth */
.theme-atletico-madrid thead th { background: var(--accent-2); color: oklch(1 0 0); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; }
.theme-atletico-madrid td { border-bottom: 1px solid var(--line); }
/* rojiblanco pinstripes wash over the hovered row */
.theme-atletico-madrid tbody tr:hover { background: repeating-linear-gradient(90deg, oklch(0.591 0.234 27.3 / 8%) 0 12px, transparent 12px 24px); }
.theme-atletico-madrid a { color: var(--accent); text-underline-offset: 3px; text-decoration-color: oklch(0.328 0.117 276.6 / 40%); }
.theme-atletico-madrid a:hover { text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
.theme-atletico-madrid ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-atletico-madrid input, .theme-atletico-madrid select, .theme-atletico-madrid textarea { border-radius: var(--radius-sm); }
.theme-atletico-madrid input:focus-visible, .theme-atletico-madrid select:focus-visible, .theme-atletico-madrid textarea:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }
.theme-atletico-madrid kbd { background: oklch(1 0 0); border: 1px solid var(--accent-2); border-bottom-width: 3px; border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); color: var(--accent-2); }
.theme-atletico-madrid ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-atletico-madrid ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-atletico-madrid ::-webkit-scrollbar-thumb { background: var(--accent-2); border-radius: 5px; border: 2px solid var(--surface-2); }
.theme-atletico-madrid ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-atletico-madrid .label-caps { color: var(--accent); }
/* shirt pinstripes on framed panels */
.theme-atletico-madrid .themed-border { border-image: repeating-linear-gradient(90deg, oklch(0.591 0.234 27.3) 0 8px, oklch(1 0 0) 8px 16px) 1; }
.theme-atletico-madrid button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-atletico-madrid.alt-mode {
  --bg: oklch(0.165 0.004 285.9);
  --surface: oklch(0.206 0.006 285.9);
  --surface-2: oklch(0.249 0.007 285.8);
  --fg: oklch(0.961 0 0);
  --fg-muted: oklch(0.682 0.009 286.2);
  --accent: oklch(0.928 0.230 124.0);
  --accent-fg: oklch(0.165 0.004 285.9);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-atletico-madrid.alt-mode { background-image: none; }
.theme-atletico-madrid.alt-mode h1 { color: #c8ff00; }
.theme-atletico-madrid.alt-mode h1 em, .theme-atletico-madrid.alt-mode h2 { color: #c8ff00; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
